mod audio;mod game;mod video;use game::Game;
fn main(){let mut captures=vec![];for typ in [58,59,67]{for y in [16,224]{let mut g=Game::new(false).unwrap();g.memory.fill(0);g.memory[0x27]=6;g.memory[0x530]=1;g.memory[0x5b0]=80;g.memory[0x570]=160;g.memory[0x720]=typ;g.memory[0x710]=80;g.memory[0x560]=y;let mut samples=vec![];for tick in 0..600 {g.memory[0x1a]=tick as u8;if g.memory[0x720]!=0 {g.actor_call(if typ==67{0xb305}else{0x8b1e},0).unwrap();}let mut shots=vec![];for j in 1..16{if g.memory[0x720+j]!=0 {shots.push(g.memory[0x720+j]);g.memory[0x720+j]=0;}}samples.push(serde_json::json!({"tick":tick,"state":g.memory[0x520],"sprite":g.memory[0x500],"type":g.memory[0x720],"flips":g.memory[0x6a],"timer":g.memory[0x660],"x":g.memory[0x710]as f32+g.memory[0x6f0]as i8 as f32*256.+g.memory[0x5c0]as f32/256.,"y":g.memory[0x560]as f32+g.memory[0x700]as i8 as f32*256.+g.memory[0x580]as f32/256.,"shots":shots}));}captures.push(serde_json::json!({"source_type":typ,"start_y":y,"samples":samples}));}}println!("{}",serde_json::to_string(&captures).unwrap());}
